// ============================================
// ROUTER: تحديد نوع الرسالة والأوامر الخاصة
// ============================================
const data = $json.body?.data?.messages;
const text = (data?.message?.conversation || data?.messageBody || '').trim();
const imageMsg = data?.message?.imageMessage;
const userId = data?.remoteJid || data?.key?.remoteJid || '';
const pushName = data?.pushName || 'صديقي';
const cleanPhone = data?.key?.cleanedSenderPn || userId.replace('@s.whatsapp.net','').replace('@lid','');

// الأوامر الخاصة
const commands = {
  summary:    ['اليوم', 'ملخص', 'كم أكلت', 'كم اكلت', 'تقريري', 'تقرير'],
  goal:       ['هدفي', 'هدف', 'اهدافي', 'أهدافي', 'معلوماتي'],
  reset:      ['يوم جديد', 'إعادة تعيين', 'اعادة تعيين', 'صفر', 'ريست'],
  delete:     ['امسح', 'احذف', 'حذف', 'مسح', 'خطأ', 'غلط'],
  setup:      ['ابدأ', 'ابدا', 'تسجيل', 'انضم', 'بريميوم', 'سيتاب', 'setup', 'start'],
  help:       ['مساعدة', 'help', 'أوامر', 'اوامر', 'شو تعمل', 'شو بتعمل']
};

let messageType = 'meal_text';
let detectedCommand = null;

if (imageMsg) {
  messageType = 'meal_image';
} else {
  const lowerText = text.toLowerCase();
  for (const [cmd, keywords] of Object.entries(commands)) {
    if (keywords.some(k => lowerText.includes(k))) {
      messageType = 'command';
      detectedCommand = cmd;
      break;
    }
  }
}

return {
  userId,
  cleanPhone,
  pushName,
  text,
  messageType,
  detectedCommand,
  hasImage: !!imageMsg,
  imageMsg: imageMsg || null,
  rawBody: $json.body
};

// استخراج بيانات السعرات من رد الـ AI + تنظيف الرسالة
const agentOutput = $json.output || '';
const userId = $('Router').item.json.userId;
const pushName = $('Router').item.json.pushName;

// استخراج JSON من آخر السطر
let caloriesData = null;
let cleanMessage = agentOutput;

const jsonMatch = agentOutput.match(/CALORIES_DATA:(\{[^}]+\})/);
if (jsonMatch) {
  try {
    caloriesData = JSON.parse(jsonMatch[1]);
    cleanMessage = agentOutput.replace(/CALORIES_DATA:\{[^}]+\}/, '').trim();
  } catch(e) {}
}

// احسب السعرات الجديدة
const userData = $('Read User (Text)').item.json || {};
const today = new Date().toISOString().split('T')[0];
const lastDate = userData.last_date || '';

let caloriesToday = parseInt(userData.calories_today || 0);
let proteinToday = parseFloat(userData.protein_today || 0);
let carbsToday = parseFloat(userData.carbs_today || 0);
let fatToday = parseFloat(userData.fat_today || 0);

// إذا يوم جديد، صفّر
if (lastDate !== today) {
  caloriesToday = 0;
  proteinToday = 0;
  carbsToday = 0;
  fatToday = 0;
}

if (caloriesData) {
  caloriesToday += caloriesData.calories || 0;
  proteinToday += caloriesData.protein || 0;
  carbsToday += caloriesData.carbs || 0;
  fatToday += caloriesData.fat || 0;
}

const caloriesTarget = parseInt(userData.calories_target || 0);
const caloriesLeft = caloriesTarget > 0 ? Math.max(0, caloriesTarget - caloriesToday) : null;

return {
  userId,
  pushName,
  cleanMessage,
  caloriesData,
  updateSheets: !!caloriesData,
  sheetUpdate: {
    calories_today: caloriesToday,
    protein_today: proteinToday,
    carbs_today: carbsToday,
    fat_today: fatToday,
    calories_left: caloriesLeft,
    last_date: today
  },
  mealLog: caloriesData ? {
    user_id: userId,
    date: today,
    time: new Date().toLocaleTimeString('ar-SA'),
    meal_name: caloriesData.meal_name || 'وجبة',
    calories: caloriesData.calories || 0,
    protein: caloriesData.protein || 0,
    carbs: caloriesData.carbs || 0,
    fat: caloriesData.fat || 0
  } : null
};

// استخراج بيانات السعرات من تحليل الصورة
const analysisText = $json['content']['parts'][0]['text'] || '';
const userId = $('Router').item.json.userId;
const pushName = $('Router').item.json.pushName;

// استخراج JSON
let caloriesData = null;
let cleanMessage = analysisText;

const jsonMatch = analysisText.match(/CALORIES_DATA:(\{[^}]+\})/);
if (jsonMatch) {
  try {
    caloriesData = JSON.parse(jsonMatch[1]);
    cleanMessage = analysisText.replace(/CALORIES_DATA:\{[^}]+\}/, '').trim();
  } catch(e) {}
}

const userData = $('Read User (Image)').item.json || {};
const today = new Date().toISOString().split('T')[0];
const lastDate = userData.last_date || '';

let caloriesToday = parseInt(userData.calories_today || 0);
let proteinToday = parseFloat(userData.protein_today || 0);
let carbsToday = parseFloat(userData.carbs_today || 0);
let fatToday = parseFloat(userData.fat_today || 0);

if (lastDate !== today) {
  caloriesToday = 0; proteinToday = 0; carbsToday = 0; fatToday = 0;
}

if (caloriesData) {
  caloriesToday += caloriesData.calories || 0;
  proteinToday += caloriesData.protein || 0;
  carbsToday += caloriesData.carbs || 0;
  fatToday += caloriesData.fat || 0;
}

const caloriesTarget = parseInt(userData.calories_target || 0);
const caloriesLeft = caloriesTarget > 0 ? Math.max(0, caloriesTarget - caloriesToday) : null;

return {
  userId,
  cleanMessage,
  caloriesData,
  sheetUpdate: {
    calories_today: caloriesToday,
    protein_today: proteinToday,
    carbs_today: carbsToday,
    fat_today: fatToday,
    calories_left: caloriesLeft,
    last_date: today
  },
  mealLog: caloriesData ? {
    user_id: userId,
    date: today,
    time: new Date().toLocaleTimeString('ar-SA'),
    meal_name: caloriesData.meal_name || 'وجبة صورة',
    calories: caloriesData.calories || 0,
    protein: caloriesData.protein || 0,
    carbs: caloriesData.carbs || 0,
    fat: caloriesData.fat || 0
  } : null
};

// معالجة الأوامر الخاصة
const command = $('Router').item.json.detectedCommand;
const pushName = $('Router').item.json.pushName;
const userData = $('Read User (Command)').item.json || {};
const userId = $('Router').item.json.userId;
const today = new Date().toISOString().split('T')[0];

const calToday = parseInt(userData.calories_today || 0);
const calTarget = parseInt(userData.calories_target || 0);
const calLeft = calTarget > 0 ? Math.max(0, calTarget - calToday) : null;
const proteinToday = parseFloat(userData.protein_today || 0);
const carbsToday = parseFloat(userData.carbs_today || 0);
const fatToday = parseFloat(userData.fat_today || 0);

// شريط تقدم
function progressBar(current, target) {
  if (!target) return '';
  const pct = Math.min(100, Math.round((current / target) * 100));
  const filled = Math.round(pct / 10);
  const bar = '█'.repeat(filled) + '░'.repeat(10 - filled);
  return `${bar} ${pct}%`;
}

let message = '';
let sheetAction = null;

switch(command) {
  case 'summary':
    const isRegistered = !!userData.calories_target;
    if (!isRegistered) {
      message = `مرحباً ${pushName} 👋\n\nما عندك هدف يومي محدد بعد.\n\nاكتب *هدفي* أو *ابدأ* لتسجيل بياناتك وتفعيل التتبع! 🎯`;
    } else {
      message = `مرحباً ${pushName} 👋\n\n📊 ملخص اليوم:\n\n🔥 السعرات:\n✅ أكلت: ${calToday} سعرة\n${calLeft !== null ? `⬜ باقي: ${calLeft} سعرة من أصل ${calTarget}` : ''}\n${progressBar(calToday, calTarget)}\n\n💪 الماكروز:\n🍗 بروتين: ${proteinToday.toFixed(1)} غ\n🍞 كربوهيدرات: ${carbsToday.toFixed(1)} غ\n🧈 دهون: ${fatToday.toFixed(1)} غ\n\nالهدف: ${userData.goal || 'غير محدد'}\n\n${calLeft === 0 ? '🎉 وصلت لهدفك اليومي!' : calLeft < 200 && calLeft > 0 ? '⚡ اقتربت من هدفك، حافظ عليه!' : ''}`;
    }
    break;

  case 'goal':
    if (!userData.calories_target) {
      message = `${pushName}، ما عندك بيانات مسجلة بعد.\n\nاكتب *ابدأ* لنسجل بياناتك ونحدد هدفك اليومي 🎯`;
    } else {
      message = `مرحباً ${pushName} 👋\n\n📋 بياناتك:\n⚖️ الوزن: ${userData.weight || '—'} كغ\n📏 الطول: ${userData.height || '—'} سم\n🎂 العمر: ${userData.age || '—'} سنة\n👤 الجنس: ${userData.gender || '—'}\n🎯 الهدف: ${userData.goal || '—'}\n\n🔥 هدفك اليومي:\n• سعرات: ${userData.calories_target || '—'}\n• بروتين: ${userData.protein_target || '—'} غ\n• كارب: ${userData.carbs_target || '—'} غ\n• دهون: ${userData.fat_target || '—'} غ`;
    }
    break;

  case 'reset':
    message = `تمام ${pushName}! ✅\n\nتم إعادة تعيين عداد اليوم.\nابدأ تسجيل وجباتك من جديد 🍽️`;
    sheetAction = 'reset';
    break;

  case 'delete':
    message = `${pushName}، ميزة حذف آخر وجبة قريباً! ⏳\n\nحالياً اكتب *يوم جديد* لتصفير العداد.`;
    break;

  case 'setup':
    message = `أهلاً ${pushName}! 🎉\n\nلتسجيل بياناتك وتفعيل التتبع، أرسل لي:\n\n👤 الجنس (ذكر/أنثى)\n🎂 العمر (بالسنوات)\n⚖️ الوزن (كغ)\n📏 الطول (سم)\n🎯 هدفك (تنزيل وزن / ثبات / زيادة كتلة)\n\nمثال: ذكر، 25، 80كغ، 178سم، تنزيل وزن`;
    break;

  case 'help':
    message = `مرحباً ${pushName}! 👋\n\n📱 الأوامر المتاحة:\n\n🥗 *تحليل وجبة* — أرسل اسم الأكل أو صورته\n📊 *اليوم* — ملخص سعراتك اليوم\n📋 *هدفي* — عرض بياناتك وهدفك\n🔄 *يوم جديد* — تصفير عداد اليوم\n🆕 *ابدأ* — تسجيل بياناتك\n\n💡 مثال: كتب *شاورما دجاج* وبعطيك التحليل الكامل`;
    break;

  default:
    message = `مرحباً ${pushName}! 👋\nما فهمت طلبك. اكتب *مساعدة* لعرض الأوامر المتاحة.`;
}

return { message, sheetAction, userId, command };

// استخدمنا first()?.json لحماية الكود من الإيرور بحال المستخدم غير مسجل
const userData = $('Check User Exists').first()?.json || {};
const isRegistered = !!(userData && userData.user_id && userData.user_id !== '');
const routerData = $('Router1').first()?.json || {};
const messageType = routerData.messageType;

let routeTo;
if (messageType === 'setup') {
  routeTo = 'register';
} else if (isRegistered) {
  routeTo = 'normal';
} else {
  routeTo = 'not_registered';
}
// دمج بيانات الراوتر مع التسجيل لتمرير البيانات الخام للصوت
return {
  ...routerData,
  routeTo,
  isRegistered,
  userData: userData
};

const routerData = $('Router1').first()?.json || {};
const text = (routerData.text || '').trim();
const pushName = routerData.pushName || 'صديقي';
const userId = routerData.userId || '';

const parts = text.replace(/^(ابدأ|ابدا)\s*/i, '').trim().split(/\s+/);

let gender = null;
let idx = 0;
const genderWord = parts[0]?.toLowerCase();
if (['ذكر','male','m'].includes(genderWord)) { gender = 'male'; idx = 1; }
else if (['انثى','أنثى','female','f'].includes(genderWord)) { gender = 'female'; idx = 1; }

const nums = parts.slice(idx).map(p => parseFloat(p.replace(/[^\d.]/g, ''))).filter(n => !isNaN(n));
const age = nums[0] || null;
const weight = nums[1] || null;
const height = nums[2] || null;

const remaining = parts.slice(idx).join(' ');
let goal = 'ثبات';
if (remaining.includes('تنزيل') || remaining.includes('خسارة') || remaining.includes('دايت')) goal = 'تنزيل وزن';
else if (remaining.includes('زيادة') || remaining.includes('كتلة') || remaining.includes('عضل')) goal = 'زيادة كتلة';
else if (remaining.includes('ثبات') || remaining.includes('محافظة')) goal = 'ثبات';

if (!gender || !age || !weight || !height) {
  return {
    success: false,
    message: `${pushName}، ما قدرت أفهم معلوماتك صح 😅\nجرب هيك:\n*ابدأ ذكر 25 80 175 تنزيل وزن*\nالترتيب: جنس - عمر - وزن(كغ) - طول(سم) - هدف`,
    userId
  };
}

let bmr;
if (gender === 'male') { bmr = 10 * weight + 6.25 * height - 5 * age + 5; }
else { bmr = 10 * weight + 6.25 * height - 5 * age - 161; }
const tdee = Math.round(bmr * 1.55);

let calTarget, proTarget, carbTarget, fatTarget;
if (goal === 'تنزيل وزن') {
  calTarget = Math.round(tdee - 500);
  proTarget = Math.round(weight * 2);
  fatTarget = Math.round(calTarget * 0.25 / 9);
  carbTarget = Math.round((calTarget - proTarget*4 - fatTarget*9) / 4);
} else if (goal === 'زيادة كتلة') {
  calTarget = Math.round(tdee + 300);
  proTarget = Math.round(weight * 2.2);
  fatTarget = Math.round(calTarget * 0.25 / 9);
  carbTarget = Math.round((calTarget - proTarget*4 - fatTarget*9) / 4);
} else {
  calTarget = tdee;
  proTarget = Math.round(weight * 1.8);
  fatTarget = Math.round(calTarget * 0.25 / 9);
  carbTarget = Math.round((calTarget - proTarget*4 - fatTarget*9) / 4);
}

const today = new Date().toISOString().split('T')[0];

const replyMsg = `🎉 تم تسجيلك ${pushName}!\n📋 معلوماتك:\n👤 الجنس: ${gender === 'male' ? 'ذكر' : 'أنثى'}\n🎂 العمر: ${age} سنة\n⚖️ الوزن: ${weight} كغ\n📏 الطول: ${height} سم\n🎯 الهدف: ${goal}\n━━━━━━━━━━━━━━━━━━━━\n🔥 هدفك اليومي المحسوب:\n• سعرات: ${calTarget}\n• بروتين: ${proTarget} غ\n• كربوهيدرات: ${carbTarget} غ\n• دهون: ${fatTarget} غ\n━━━━━━━━━━━━━━━━━━━━\nهلق ابدأ تبعتلي أكلك وأنا أحسبلك! 💪\nمثال: *شاورما دجاج* أو أبعتلي صورة 📸`;

return {
  success: true,
  message: replyMsg,
  userId,
  sheetData: {
    user_id: userId,
    name: pushName,
    gender,
    age,
    weight,
    height,
    goal,
    calories_target: calTarget,
    protein_target: proTarget,
    carbs_target: carbTarget,
    fat_target: fatTarget,
    calories_today: 0,
    protein_today: 0,
    carbs_today: 0,
    fat_today: 0,
    calories_left: calTarget,
    protein_left: proTarget,
    carbs_left: carbTarget,
    fat_left: fatTarget,
    last_date: today,
    start_date: today
  }
};

const msgData = $json.body?.data || $json.body;
const text = (msgData?.message?.conversation || msgData?.message?.extendedTextMessage?.text || '').trim();
const imageMsg = msgData?.message?.imageMessage;
// قراءة الرسالة الصوتية من الواتساب
const audioMsg = msgData?.message?.audioMessage || msgData?.message?.voiceMessage || msgData?.message?.documentMessage;
const userId = msgData?.key?.remoteJid || msgData?.remoteJid || '';
const pushName = msgData?.pushName || 'صديقي';

const commands = {
  summary: ['اليوم','ملخص','كم اكلت','كم أكلت','تقريري','تقرير'],
  goal:    ['هدفي','هدف','معلوماتي'],
  reset:   ['يوم جديد','اعادة تعيين','إعادة تعيين','صفر','ريست'],
help: ['مساعدة','help','اوامر','أوامر','شو تعمل','مرحبا','كيفك','هلا','سلام','السلام','صباح الخير','مساء الخير']
};

let messageType = 'meal_text';
let detectedCommand = null;

if (audioMsg) {
  messageType = 'meal_audio';
} else if (imageMsg) {
  messageType = 'meal_image';
} else {
  const lower = text.toLowerCase();
  if (lower.startsWith('ابدأ') || lower.startsWith('ابدا')) {
    messageType = 'setup';
  } else {
    for (const [cmd, keywords] of Object.entries(commands)) {
if (keywords.some(k => lower === k)) {        messageType = 'command';
        detectedCommand = cmd;
        break;
      }
    }
  }
}

return { userId, pushName, text, messageType, detectedCommand, hasImage: !!imageMsg, hasAudio: !!audioMsg, rawBody: $json.body };

const checkReg = $('Check Registration').first()?.json || {};
const router = $('Router1').first()?.json || {};
const userData = $('Check User Exists').first()?.json || {};

const cmd = checkReg.detectedCommand;
const pushName = String(router.pushName || 'صديقي').trim();

function number(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function round(value) {
  return Math.round(value * 10) / 10;
}

function progressBar(current, target) {
  if (!target) return '';

  const percentage = Math.max(
    0,
    Math.round((current / target) * 100)
  );

  const visualPercentage = Math.min(100, percentage);
  const filled = Math.round(visualPercentage / 10);

  return (
    '█'.repeat(filled) +
    '░'.repeat(10 - filled) +
    ` ${percentage}%`
  );
}

const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Damascus',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

const caloriesTarget = number(userData.calories_target);
const proteinTarget = number(userData.protein_target);
const carbsTarget = number(userData.carbs_target);
const fatTarget = number(userData.fat_target);

// إذا بدأ يوم جديد، نعرض العدادات صفراً حتى قبل تسجيل أول وجبة
const isCurrentDay = String(userData.last_date || '') === today;

const caloriesToday = isCurrentDay
  ? number(userData.calories_today)
  : 0;

const proteinToday = isCurrentDay
  ? number(userData.protein_today)
  : 0;

const carbsToday = isCurrentDay
  ? number(userData.carbs_today)
  : 0;

const fatToday = isCurrentDay
  ? number(userData.fat_today)
  : 0;

const caloriesLeft = round(caloriesTarget - caloriesToday);
const proteinLeft = round(proteinTarget - proteinToday);
const carbsLeft = round(carbsTarget - carbsToday);
const fatLeft = round(fatTarget - fatToday);

const goalText = {
  loss: 'تنزيل وزن',
  maintain: 'تثبيت الوزن',
  gain: 'زيادة كتلة',
  'تنزيل وزن': 'تنزيل وزن',
  'ثبات': 'تثبيت الوزن',
  'زيادة كتلة': 'زيادة كتلة'
}[userData.goal] || 'غير محدد';

const activityText = {
  sedentary: 'قليل جداً',
  light: 'خفيف',
  moderate: 'متوسط',
  high: 'عالٍ'
}[userData.activity] || 'غير محدد';

let message = '';
let sheetAction = null;

switch (cmd) {
  case 'summary': {
    if (!caloriesTarget) {
      message =
`بيانات حسابك ناقصة يا ${pushName}.
اكتب «مساعدة» لعرض الخيارات المتاحة.`;
      break;
    }

    const caloriesStatus = caloriesLeft > 0
      ? `⬜ باقي: ${caloriesLeft} سعرة من أصل ${caloriesTarget}`
      : caloriesLeft === 0
        ? '🎉 وصلت لهدف السعرات اليومي!'
        : `⚠️ تجاوزت هدفك بـ ${Math.abs(caloriesLeft)} سعرة`;

    message =
`مرحباً ${pushName} 👋

📊 ملخص اليوم:

🔥 السعرات:
✅ أكلت: ${caloriesToday} سعرة
${caloriesStatus}
${progressBar(caloriesToday, caloriesTarget)}

💪 الماكروز:
🍗 بروتين: ${proteinToday} غ — باقي ${Math.max(0, proteinLeft)} غ
🍞 كارب: ${carbsToday} غ — باقي ${Math.max(0, carbsLeft)} غ
🥑 دهون: ${fatToday} غ — باقي ${Math.max(0, fatLeft)} غ

🎯 الهدف: ${goalText}`;

    break;
  }

  case 'goal': {
    if (!caloriesTarget) {
      message =
`بيانات هدفك ناقصة يا ${pushName}.
اكتب «مساعدة» لعرض الخيارات المتاحة.`;
      break;
    }

    message =
`🎯 بياناتك الحالية يا ${pushName}:

⚖️ الوزن: ${userData.weight || '—'} كغ
📏 الطول: ${userData.height || '—'} سم
🎂 العمر: ${userData.age || '—'} سنة
🏃 النشاط: ${activityText}
🎯 الهدف: ${goalText}

🔥 أهدافك اليومية:
• السعرات: ${caloriesTarget} سعرة
• البروتين: ${proteinTarget} غ
• الكارب: ${carbsTarget} غ
• الدهون: ${fatTarget} غ`;

    break;
  }

  case 'reset': {
    message =
`ما في داعي لتصفير اليوم يدوياً يا ${pushName} ✅

البوت بيفصل كل يوم تلقائياً حسب تاريخ دمشق، وبيبدأ حساب جديد من أول وجبة.`;

    break;
  }

  case 'help': {
    message =
`مرحباً ${pushName}! 👋

أنا مساعدك لمتابعة السعرات والماكروز 💪

🥗 لتسجيل وجبة:
ابعتلي شو أكلت مع الكمية.
مثال: أكلت بيضتين مسلوقتين بدون إضافات

