const data = $input.first().json;

const age = Number(data.age);
const weight = Number(data.weight);
const height = Number(data.height);

// معادلة Mifflin-St Jeor
const bmr = data.gender === 'male'
  ? (10 * weight) + (6.25 * height) - (5 * age) + 5
  : (10 * weight) + (6.25 * height) - (5 * age) - 161;

// معامل النشاط
const activityFactors = {
  sedentary: 1.2,
  light: 1.375,
  moderate: 1.55,
  high: 1.725
};

const activityFactor = activityFactors[data.activity] || 1.2;
const tdee = Math.round(bmr * activityFactor);

// حساب هدف السعرات
let caloriesTarget;

if (data.goal === 'loss') {
  const deficit = Math.min(500, tdee * 0.20);
  const minimumCalories = data.gender === 'male' ? 1500 : 1200;
  caloriesTarget = Math.max(minimumCalories, tdee - deficit);
} else if (data.goal === 'gain') {
  caloriesTarget = tdee + 250;
} else {
  caloriesTarget = tdee;
}

// تقريب السعرات لأقرب 10
caloriesTarget = Math.round(caloriesTarget / 10) * 10;

// البروتين بحسب الهدف
const proteinFactors = {
  loss: 2,
  maintain: 1.6,
  gain: 1.8
};

const proteinTarget = Math.round(
  weight * (proteinFactors[data.goal] || 1.6)
);

// الدهون = تقريباً 25% من السعرات
const fatTarget = Math.round(
  (caloriesTarget * 0.25) / 9
);

// الكارب من السعرات المتبقية
const carbsTarget = Math.max(
  0,
  Math.round(
    (caloriesTarget - (proteinTarget * 4) - (fatTarget * 9)) / 4
  )
);

